draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw System 1 (fast)
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 50);
  ctx.lineTo(W/4, H/2 - 70 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4, H/2 + 70 - 20 * Math.sin(t));
  ctx.stroke();

  // Draw System 2 (slow)
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 - 50);
  ctx.lineTo(W - W/4, H/2 - 70 + 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4, H/2 + 70 - 20 * Math.cos(t));
  ctx.stroke();

  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('System 1', W/4, H/2 - 100);
  ctx.fillText('System 2', W - W/4, H/2 - 100);

  ctx.restore();
}
